#!/usr/bin/env python3"""Generate the Keycloak operator realm import from the committed realm file (G1-M4.3).The Keycloak Operator (``k8s.keycloak.org/v2alpha1``) imports a realm from a``KeycloakRealmImport`` custom resource, so the cluster receives exactly the realmthe local profile uses instead of an admin-console session.The resource embeds the realm, which makes it a second copy of``deploy/keycloak/realm/spectrace-realm.json``. Two guards keep the copies fromdrifting apart: this script is the only writer, and``KeycloakOperatorRealmImportContractTest`` (backend suite, runs in CI) fails whenthe committed resource no longer matches the realm file.Demo credentials are never copied into the resource. Each demo user's passwordbecomes a ``${DEMO_PASSWORD_<USER>}`` placeholder whose value comes from the``spectrace-demo-credentials`` Secret when the resource is applied, so thepipeline injects staging credentials and no password is committed.Usage:    python3 deploy/keycloak/scripts/generate-realm-import.py          # write it    python3 deploy/keycloak/scripts/generate-realm-import.py --check  # verify only"""import argparseimport jsonimport osimport reimport sysSCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))KEYCLOAK_DIR = os.path.dirname(SCRIPT_DIR)REALM_FILE = os.path.join(KEYCLOAK_DIR, "realm", "spectrace-realm.json")IMPORT_FILE = os.path.join(KEYCLOAK_DIR, "operator", "keycloak-realm-import.yaml")RESOURCE_NAME = "spectrace-realm"NAMESPACE = "keycloak"KEYCLOAK_CR_NAME = "spectrace-keycloak"CREDENTIALS_SECRET = "spectrace-demo-credentials"HEADER = [    "# Generated by deploy/keycloak/scripts/generate-realm-import.py from",    "# deploy/keycloak/realm/spectrace-realm.json - do not edit by hand.",    "#",    "# The Keycloak Operator imports this resource when the staging window opens.",    "# Demo credentials come from the %s Secret" % CREDENTIALS_SECRET,    "# (the placeholders below) and are never committed.",]def placeholder(username):    """Operator placeholder names are identifiers, so usernames are sanitised."""    return "DEMO_PASSWORD_" + re.sub(r"[^A-Za-z0-9]", "_", username).upper()def realm_with_placeholders(realm):    """Returns a detached realm copy plus its (placeholder, username) pairs."""    realm = json.loads(json.dumps(realm))    pairs = []    for user in realm.get("users", []):        username = user["username"]        credentials = user.get("credentials") or []        if len(credentials) != 1 or credentials[0].get("type") != "password":            raise SystemExit(                "realm user %s must carry exactly one password credential" % username            )        name = placeholder(username)        credentials[0]["value"] = "${%s}" % name        pairs.append((name, username))    if not pairs:        raise SystemExit("the realm file declares no demo users")    return realm, pairsdef render(realm):    """Renders the custom resource. JSON is valid YAML, so the realm is a JSON block."""    placeholder_realm, pairs = realm_with_placeholders(realm)    lines = list(HEADER)    lines.append("apiVersion: k8s.keycloak.org/v2alpha1")    lines.append("kind: KeycloakRealmImport")    lines.append("metadata:")    lines.append("  name: %s" % RESOURCE_NAME)    lines.append("  namespace: %s" % NAMESPACE)    lines.append("spec:")    lines.append("  # Name of the Keycloak custom resource in the same namespace.")    lines.append("  keycloakCRName: %s" % KEYCLOAK_CR_NAME)    lines.append("  placeholders:")    for name, username in pairs:        lines.append("    %s:" % name)        lines.append("      secret:")        lines.append("        name: %s" % CREDENTIALS_SECRET)        lines.append("        key: %s" % username)    lines.append("  realm:")    for line in json.dumps(placeholder_realm, indent=2).splitlines():        lines.append("    " + line)    return "\n".join(lines) + "\n"def main(argv):    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])    parser.add_argument(        "--check",        action="store_true",        help="fail instead of writing when the committed resource is stale",    )    args = parser.parse_args(argv)    with open(REALM_FILE, "r", encoding="utf-8") as handle:        realm = json.load(handle)    rendered = render(realm)    if args.check:        try:            with open(IMPORT_FILE, "r", encoding="utf-8") as handle:                committed = handle.read()        except IOError:            print("missing %s; run the generator" % IMPORT_FILE, file=sys.stderr)            return 1        if committed != rendered:            print(                "%s is out of date; regenerate it from the realm file" % IMPORT_FILE,                file=sys.stderr,            )            return 1        print("KeycloakRealmImport matches the committed realm file.")        return 0    directory = os.path.dirname(IMPORT_FILE)    if not os.path.isdir(directory):        os.makedirs(directory)    with open(IMPORT_FILE, "w", encoding="utf-8", newline="\n") as handle:        handle.write(rendered)    print("Wrote %s" % IMPORT_FILE)    return 0if __name__ == "__main__":    sys.exit(main(sys.argv[1:]))